local UIWorldBossMainDialog2 = Class('UIWorldBossMainDialog2')



function UIWorldBossMainDialog2:__init()
    self._curBossPlanId = nil        --当前bossid
    self._curBossPlanVo = nil        --当前bossVo
    self.EventWorldBossBegin = nil
    self.EventWorldBossEnd = nil
    self.rankListData = {
        prefabPath = "Prefabs/WorldBoss/WorldBossPlayerRankingsDialog.prefab",
        srcPath = "Game.UI.FightReady.UIWorldBoss.UIWorldBossPlayerRankingsDialog.UIWorldBossPlayerRankingsDialog2",
        controller = nil,
        go = nil
    }
end

function UIWorldBossMainDialog2:__delete()

end

function UIWorldBossMainDialog2:Awake()
end



function UIWorldBossMainDialog2:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        CriWareUtils.PlayMusicById("bgm_world_boss")

        -- TODO: ???
        CfUtils.RefreshTopGoods({})

        -- 获取当前的世界BOSS信息
        worldBossComponent:RefreshWorldBossInfo(function()
            self._curBossPlanId = worldBossComponent:GetCurBossPlanId()
            if not self._curBossPlanId then return end

            self._curBossPlanVo = CfUtils.GetCfVo(AutoIds.IdSetting979, "WorldBossPlanVo", checkString(self._curBossPlanId))
            if not self._curBossPlanVo then return end

            CfUtils.FillImage(self.Bg, self._curBossPlanVo.modelId)

            self:FillSelf()
            SetButtonAction(self.Btncheck, Bind(self, self.OnClickShowBossInfoHandler))
            SetButtonAction(self.FontStyleButton, Bind(self, self.OnClickTeamBuildHandler))
            SetButtonAction(self.BtnList, Bind(self, self.OnClickBtnListHandler))
            SetButtonAction(self.BtnReward, Bind(self, self.OnClickBtnRewardHandler))

            self.CoLoadRankPanel = cs_coroutine.start(function()
                self.rankListData.go = GameUtils.LoadBundleAsync(self.rankListData.prefabPath, self.controller.gameObject, false)
                if not self.rankListData.go then return end
                self.rankListData.controller = CfUtils.GetLuaScr(self.rankListData.go, self.rankListData.srcPath)

                local rankInfoData = {}
                --- 从服务器获取排行表信息
                GameUtils.Request(Interfaces.WorldBossRank, {}, function(request, response)
                    if checkNumber(response.errCode) ~= 0 then
                        GameUtils.Toast(localize("请求失败"))
                        return
                    end
                    local RankingListDojo = import("Game.Dojo.RankingListDojo")

                    local jsonData = response.data
                    local rankInfo = jsonData.rankInfo
                    local t = {}
                    for k, v in pairs(rankInfo) do
                        local dojo = RankingListDojo.New()
                        dojo:Fill(v)
                        dojo.rankNum = checkNumber(k)
                        table.insert(t, dojo)
                    end

                    rankInfoData.rankList = t

                    local myRankData = {
                        myRankInfo = worldBossComponent:GetCurRankInfo(),
                        myHurt = worldBossComponent:GetCurRankInfo().hurt
                    }

                    rankInfoData.myRankData = myRankData

                    rankInfoData.percentageRank = checkNumber(jsonData.percentageRank)

                    self.rankListData.controller:UpdateInfo(rankInfoData)
                end)
            end)
        end)
    end))
    return coWait
end

function UIWorldBossMainDialog2:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        if not isNull(self._timeDown) then
            CDTimerModule.GetInstance():RemoveCD(self._timeDown)
            self._timeDown = nil
        end

        if self.CoLoadRankPanel then
            cs_coroutine.stop(self.CoLoadRankPanel)
        end

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

----------------------------------
--- private function

function UIWorldBossMainDialog2:FillSelf()
    self._curWorldBossVo = QuestConfMgr:GetInstance():GetWorldBossBossVo(self._curBossPlanId)
    if not self._curWorldBossVo then end

    self._curBossCardSkin = CfUtils.GetCfVo(AutoIds.IdSetting113, "CardSkinVo", self._curWorldBossVo.skinId)
    if not self._curBossCardSkin then return end

    CfUtils.FillText(self.TxtName, self._curBossCardSkin.name)

    local isOpen = worldBossComponent:IsOpen()
    KTool.SetActive(self.BtnList, isOpen)
    KTool.SetActive(self.BtnReward, isOpen)


    self:UpdateTimeDown()
end

function UIWorldBossMainDialog2:UpdateTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
    end

    local durTime = worldBossComponent:GetBossDurationTime()
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        local time = worldBossComponent:GetRemainTime()
        local isOpen = worldBossComponent:IsOpen()
        local desc = ""
        if isOpen then
            desc = localize("离封锁关闭时间")..CfUtils.GetTimeHMS2(checkNumber(durTime) - math.abs(time))
        else
            desc = localize("离封锁开启时间")..CfUtils.GetTimeHMS2(math.abs(time))
            CfUtils.SetActive(self.FontStyleButton.transform:Find("ImgBlack").gameObject, true)
        end

        CfUtils.FillText(self.TextTime, desc)
    end, CountDownTime, false, true)
end

