function UIWorldBossMainDialog2:OnClickShowBossInfoHandler()
    UIModule.OpenDialog({
        id = Constants.UITypeIds.UIWorldBossDetailsDialog
    }, {
        { id = Constants.UITypeIds.UIWorldBossMainDialog }
    })
end

function UIWorldBossMainDialog2:OnClickTeamBuildHandler()
    if not worldBossComponent:IsOpen() then
        GameUtils.Toast(localize("活动未开启"))
        return
    end
    UIModule.OpenDialog({
        id = Constants.UITypeIds.UIFightTeamChoose,
        parameters = {
            levelId = self._curBossPlanVo.range
        }
    },{
        {id = Constants.UITypeIds.UIWorldBossMainDialog}
    })
end

function UIWorldBossMainDialog2:OnClickBtnListHandler()
    UIModule.OpenDialog({
        id = Constants.UITypeIds.UIWorldBossRankRewardDialog
    }, {
        --{ id = Constants.UITypeIds.UIWorldBossMainDialog }
    })
end

